package ir.kheili.gallery;

import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.Color;import android.provider.Settings;import android.view.*;import android.widget.*;import androidx.activity.result.ActivityResultLauncher;import androidx.activity.result.contract.ActivityResultContracts;import androidx.annotation.NonNull;import androidx.appcompat.app.AppCompatActivity;import androidx.biometric.BiometricManager;import androidx.biometric.BiometricPrompt;import androidx.core.content.ContextCompat;import java.util.concurrent.Executor;

public class MainActivity extends AppCompatActivity {
 private LinearLayout root, content; private final int ink=Color.rgb(23,33,43), accent=Color.rgb(63,107,100); private ActivityResultLauncher<String[]> picker;
 @Override public void onCreate(Bundle b){super.onCreate(b); getWindow().setStatusBarColor(Color.rgb(248,247,243)); showGate(); picker=registerForActivityResult(new ActivityResultContracts.OpenDocument(), uri->{ if(uri!=null) try{new VaultStore(this).importUri(uri,uri.getLastPathSegment()==null?"فایل":uri.getLastPathSegment()); Toast.makeText(this,"فایل رمزنگاری و ذخیره شد",Toast.LENGTH_SHORT).show();}catch(Exception e){Toast.makeText(this,"ذخیره فایل انجام نشد",Toast.LENGTH_LONG).show();} });}
 private TextView t(String s,int size){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(ink);v.setGravity(Gravity.RIGHT);v.setPadding(0,10,0,10);return v;}
 private void base(){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(28,32,28,20);root.setBackgroundColor(Color.rgb(248,247,243));setContentView(root);}
 private void showGate(){base(); Space sp=new Space(this);root.addView(sp,new LinearLayout.LayoutParams(1,0,1)); TextView title=t("گالری شخصی",30);title.setGravity(Gravity.CENTER);root.addView(title);TextView sub=t("عکس‌ها و ویدئوهای خصوصی شما",16);sub.setGravity(Gravity.CENTER);root.addView(sub); Button bio=new Button(this);bio.setText("ورود با اثر انگشت");root.addView(bio,new LinearLayout.LayoutParams(-1,58)); Button pin=new Button(this);pin.setText("ورود با کد");root.addView(pin,new LinearLayout.LayoutParams(-1,58)); TextView hint=t("اطلاعات شما فقط روی همین دستگاه نگهداری می‌شود",13);hint.setGravity(Gravity.CENTER);root.addView(hint);root.addView(new Space(this),new LinearLayout.LayoutParams(1,0,1)); bio.setOnClickListener(v->biometric());pin.setOnClickListener(v->pinDialog());}
 private void biometric(){if(BiometricManager.from(this).canAuthenticate(BiometricManager.Authenticators.BIOMETRIC_STRONG|BiometricManager.Authenticators.DEVICE_CREDENTIAL)!=BiometricManager.BIOMETRIC_SUCCESS){pinDialog();return;} Executor ex=ContextCompat.getMainExecutor(this);BiometricPrompt p=new BiometricPrompt(this,ex,new BiometricPrompt.AuthenticationCallback(){public void onAuthenticationSucceeded(@NonNull BiometricPrompt.AuthenticationResult r){openHome();}});p.authenticate(new BiometricPrompt.PromptInfo.Builder().setTitle("ورود به گالری شخصی").setSubtitle("هویت خود را تأیید کنید").setNegativeButtonText("استفاده از کد").build());}
 private void pinDialog(){final EditText e=new EditText(this);e.setInputType(2);e.setHint("کد چهار رقمی");new AlertDialog.Builder(this).setTitle("کد ورود").setMessage("کد شخصی را وارد کنید").setView(e).setPositiveButton("ورود",(d,w)->{if(e.getText().toString().length()>=4)openHome();else Toast.makeText(this,"کد باید حداقل ۴ رقم باشد",Toast.LENGTH_SHORT).show();}).setNegativeButton("انصراف",null).show();}
 private void openHome(){base();TextView head=t("فضای شخصی",28);root.addView(head);TextView welcome=t("همه‌چیز مرتب و در کنترل شماست",15);welcome.setTextColor(Color.DKGRAY);root.addView(welcome);EditText search=new EditText(this);search.setHint("جست‌وجوی عکس، ویدئو یا پوشه...");root.addView(search);content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);root.addView(content,new LinearLayout.LayoutParams(-1,0,1)); render("همه موارد");LinearLayout nav=new LinearLayout(this);nav.setGravity(Gravity.CENTER);String[] tabs={"همه","عکس‌ها","ویدئوها","پوشه‌ها"};for(String s:tabs){Button q=new Button(this);q.setText(s);nav.addView(q,new LinearLayout.LayoutParams(0,58,1));q.setOnClickListener(v->render(s));}root.addView(nav);Button add=new Button(this);add.setText("＋ افزودن فایل به فضای شخصی");root.addView(add,new LinearLayout.LayoutParams(-1,60));add.setOnClickListener(v->picker.launch(new String[]{"image/*","video/*"}));}
 private void render(String section){content.removeAllViews();TextView h=t(section,21);content.addView(h);TextView empty=t("هنوز فایلی اضافه نشده است\nاز دکمه پایین برای انتخاب عکس یا ویدئو استفاده کنید.",16);empty.setTextColor(Color.DKGRAY);content.addView(empty);}
}
